def transform(grid):
    out = [row[:] for row in grid]
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    if len(ones) == 2:
        (r1, c1), (r2, c2) = ones
        dr = 1 if r2 > r1 else -1 if r2 < r1 else 0
        dc = 1 if c2 > c1 else -1 if c2 < c1 else 0
        r, c = r1 + dr, c1 + dc
        while (r, c) != (r2, c2):
            if grid[r][c] != 6:
                out[r][c] = 1
            r += dr
            c += dc
    # Each 6 paints its full diagonal (slope opposite to the line between 1s).
    sixes = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]
    if len(ones) == 2 and sixes:
        (r1, c1), (r2, c2) = ones
        dr = 1 if r2 > r1 else -1 if r2 < r1 else 0
        dc = 1 if c2 > c1 else -1 if c2 < c1 else 0
        for sr, sc in sixes:
            r, c = sr, sc
            while 0 <= r-dr < len(grid) and 0 <= c+dc < len(grid[0]):
                r -= dr; c += dc
            while 0 <= r < len(grid) and 0 <= c < len(grid[0]):
                if grid[r][c] not in (1, 6):
                    out[r][c] = 6
                r += dr; c -= dc
    return out
