def transform(grid):
    out = [row[:] for row in grid]
    ones = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 1]
    sixes = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 6]
    if len(ones) == 2:
        pairs = [(ones[0], ones[1])]
    elif len(ones) == 4:
        pairs = [(ones[0], ones[2]), (ones[1], ones[3])]
    else:
        pairs = []
    lines = []
    for (r0,c0),(r1,c1) in pairs:
        dx, dy = abs(c1-c0), abs(r1-r0)
        sx = 1 if c0 < c1 else -1
        sy = 1 if r0 < r1 else -1
        err = dx-dy
        r,c = r0,c0
        cells=[]
        while True:
            cells.append((r,c))
            if grid[r][c] != 6:
                out[r][c] = 1
            if (r,c) == (r1,c1):
                break
            e2=2*err
            if e2 > -dy:
                err -= dy
                c += sx
            if e2 < dx:
                err += dx
                r += sy
        lines.append((cells, r1-r0, c1-c0))
    # A 6 on a connector continues on the perpendicular diagonal.
    for cells, dr, dc in lines:
        if dr and dc and abs(dr)==abs(dc):
            for sr,sc in sixes:
                if (sr,sc) in cells:
                    for rr,cc in ((-1,1),(1,-1)):
                        r,c=sr+rr,sc+cc
                        while 0<=r<len(grid) and 0<=c<len(grid[0]):
                            if grid[r][c] not in (1,6):
                                out[r][c]=6
                            r+=rr
                            c+=cc
    return out
