def transform(grid):
    # Demo rule: connect the two 1 pixels by the straight diagonal;
    # markers of 6 do not alter the connector unless encountered.
    out = [row[:] for row in grid]
    ones = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 1]
    if len(ones) == 2:
        (r0,c0),(r1,c1) = ones
        dr = 1 if r1 > r0 else -1 if r1 < r0 else 0
        dc = 1 if c1 > c0 else -1 if c1 < c0 else 0
        r,c = r0,c0
        while True:
            if grid[r][c] != 6:
                out[r][c] = 1
            if (r,c) == (r1,c1):
                break
            r += dr
            c += dc
    return out
